"On the crucifix, make the Sign of the Cross and pray the Soul of Christ (Anima Christi).": "Sur le crucifix, faites le signe de croix et priez l’Âme du Christ (Anima Christi).",
"On each small bead, pray “Sweet Heart of Jesus, be my love.”": "Sur chaque petit grain, priez « Doux Cœur de Jésus, sois mon amour. »",
"After each group of small beads, pray “Sweet Heart of Mary, be my salvation.”": "Après chaque groupe de petits grains, priez « Doux Cœur de Marie, sois mon salut. »",
