"Walk with Jesus through Matthew, Mark, Luke, and John in a month.": "Marchez avec Jésus à travers Matthieu, Marc, Luc et Jean en un mois.",
"Start this plan": "Commencer ce plan",
"Psalms and Proverbs": "Psaumes et Proverbes",
