"Simple Words": "En mots simples",
"Ten questions drawn at random from the saints, books, Church history, the Bible, and theology on Sanctify. Every quiz is different.": "Dix questions tirées au hasard sur les saints, les livres, l’histoire de l’Église, la Bible et la théologie de Sanctify. Chaque quiz est différent.",
"Start the quiz": "Commencer le quiz",
