"Erase your saved entries, novenas, intentions, prayer record, badges, and settings from this device? This can’t be undone. You may want to download a backup first.": "Effacer de cet appareil vos éléments enregistrés, neuvaines, intentions, suivi de prière, badges et réglages ? C’est irréversible. Vous pouvez d’abord télécharger une sauvegarde.",
