"follows the Roman Missal of 1962 and its calendar: the old feasts and seasons, Ember Days, the Latin Mass explained, and the fifteen mysteries of the Rosary. Its prayers are those of the Roman Catholic edition.": "suit le Missel romain de 1962 et son calendrier : les anciennes fêtes et saisons, les Quatre-Temps, la messe latine expliquée et les quinze mystères du Rosaire. Ses prières sont celles de l’édition catholique romaine.",
